import { NgClass, NgTemplateOutlet } from '@angular/common';
import { AfterContentChecked, ChangeDetectorRef, Component, computed, ElementRef, EventEmitter, inject, input, Input, Output, signal, ViewChild } from '@angular/core';
import { SafeHtml } from '@angular/platform-browser';
import { RouterLink } from '@angular/router';
import { ApplicationConfig, MODULE_NAME } from 'espd-common/config';
import { MessageComponent } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { SettingService, SettingType } from 'espd-common/setting';
import { CollapseDirective } from 'ngx-bootstrap/collapse';

@Component({
	selector: 'espd-header',
	templateUrl: 'header.component.html',
	styleUrls: ['header.component.scss'],
	exportAs: 'header',
	imports: [CollapseDirective, IconDirective, MessageComponent, NgClass, NgTemplateOutlet, RouterLink],
})
export class HeaderComponent implements AfterContentChecked {

	@Input() applicationNameDisplay = true;
	@Input() subtitle = '';
	@Input() lockupRoute?: string;
	@Input() lockupHref?: string;
	customHeaderOverride = input<SafeHtml>();
	@Input() user?: { username: string, initials: string };
	@Input() fullWidth = false;
	@Output() readonly lockupClicked = new EventEmitter<void>();
	@Output() readonly mobileMenuClicked: EventEmitter<boolean> = new EventEmitter<boolean>();

	@ViewChild('mobileMenuRef') mobileMenuRef?: ElementRef<HTMLElement>;

	public applicationName?: string;
	public logoUrl?: string;
	public logoMobileUrl?: string;
	public logoDisplay = true;
	public mobileMenuOpen = false;

	private customHeaderSetting = signal<string | undefined>(undefined);
	public customHeader = computed(() => this.customHeaderOverride() ?? this.customHeaderSetting());

	private changeDetector = inject(ChangeDetectorRef);

	constructor() {
		const appConfig = inject(ApplicationConfig);
		const settingService = inject(SettingService);
		settingService.waitFor(MODULE_NAME).subscribe(() => {
			this.customHeaderSetting.set(settingService.get(SettingType.CUSTOM_HEADER) as string);
			this.applicationName = settingService.get(appConfig.applicationNameSetting) as string;
			this.logoUrl = settingService.get(SettingType.LOGO_URL) as string;
			this.logoMobileUrl = settingService.get(SettingType.LOGO_URL_MOBILE) as string;
			this.logoDisplay = settingService.get(SettingType.LOGO_DISPLAY) as boolean;
		});
	}

	public ngAfterContentChecked(): void {
		// Because mobileMenuRef is assigned during content init,
		// and it is not marked as static anymore,
		// we need to detect changes to prevent changeAfterChecked errors
		// on the hasMobileContent field
		this.changeDetector.detectChanges();
	}

	public get hasMobileContent(): boolean {
		// If there are no children, there was no mobile menu content projected
		// and therefore we shouldn't show the mobile menu toggle button.
		return !!this.mobileMenuRef?.nativeElement.children.length;
	}

	public headerClicked(): void {
		this.lockupClicked.emit();
	}

	public mobileClicked(): void {
		this.mobileMenuOpen = !this.mobileMenuOpen;
		this.mobileMenuClicked.emit(this.mobileMenuOpen);
	}

	public closeMobileMenu(): void {
		this.mobileMenuOpen = false;
		this.mobileMenuClicked.emit(this.mobileMenuOpen);
	}
}