import { Component, HostBinding, Input, OnChanges, ViewChild, inject } from '@angular/core';
import { IsActiveMatchOptions, Params, RouterLinkActive } from '@angular/router';
import { HeaderNavComponent } from '../header-nav.component';

@Component({
	selector: 'espd-header-nav-item',
	templateUrl: './header-nav-item.component.html',
	styleUrls: ['./header-nav-item.component.scss'],
	standalone: false
})
export class HeaderNavItemComponent implements OnChanges {

	@Input() public route?: string;
	@Input() public queryParams: Params | null = null;
	@Input() public href?: string;
	@Input() public linkActiveOptions: Partial<IsActiveMatchOptions> = {};

	@HostBinding('class.nested')
	public nested = false;

	@HostBinding('attr.role')
	public readonly role = 'listitem';

	@ViewChild('rla')
	private routerLinkActive?: RouterLinkActive;

	private parentHeaderNav: HeaderNavComponent = inject(HeaderNavComponent);

	public isActiveMatchOptions: IsActiveMatchOptions = HeaderNavComponent.defaultActiveMatchOptions;

	public ngOnChanges(): void {
		// This is a bit odd, but if the value is computed directly in the getter for isActiveMatchOptions, an infinite loop occurs
		this.isActiveMatchOptions = { ...this.parentHeaderNav.isActiveMatchOptions, ...this.linkActiveOptions };
	}

	public get isActive(): boolean {
		return this.routerLinkActive?.isActive ?? false;
	}

}
