import { Component, Input, OnChanges, inject } from '@angular/core';
import { IsActiveMatchOptions } from '@angular/router';
import { MessageConfig, MessageService } from 'espd-common/i18n';

@Component({
	selector: 'espd-header-nav',
	templateUrl: './header-nav.component.html',
	styleUrls: ['./header-nav.component.scss'],
	standalone: false
})
export class HeaderNavComponent implements OnChanges {

	public static defaultActiveMatchOptions: IsActiveMatchOptions = {
		fragment: 'ignored',
		matrixParams: 'ignored',
		paths: 'exact',
		queryParams: 'ignored'
	}

	@Input()
	public label?: string | MessageConfig;

	@Input()
	public linkActiveOptions: Partial<IsActiveMatchOptions> = HeaderNavComponent.defaultActiveMatchOptions;

	public ariaLabel = '';

	private matchOptions = HeaderNavComponent.defaultActiveMatchOptions;
	private messageService: MessageService = inject(MessageService);

	public ngOnChanges(): void {
		// This is a bit odd, but if the value is computed directly in the getter for isActiveMatchOptions, an infinite loop occurs
		this.matchOptions = { ...HeaderNavComponent.defaultActiveMatchOptions, ...this.linkActiveOptions };
		this.ariaLabel = this.messageService.evaluate(this.label ?? '');
	}

	public get isActiveMatchOptions(): IsActiveMatchOptions {
		return this.matchOptions;
	}
}
