import { AfterContentInit, Component, ContentChildren, HostBinding, Input, QueryList } from '@angular/core';
import { MessageConfig } from 'espd-common/i18n';
import { HeaderNavItemComponent } from '../header-nav-item/header-nav-item.component';

@Component({
	selector: 'espd-header-nav-list',
	templateUrl: './header-nav-list.component.html',
	styleUrls: ['./header-nav-list.component.scss'],
	standalone: false
})
export class HeaderNavListComponent implements AfterContentInit {

	private static nextId = 0;

	@Input() public label: string | MessageConfig = '';
	@Input() public dropRight = false;

	public id: number;

	@HostBinding('attr.role')
	public readonly role = 'listitem';

	@ContentChildren(HeaderNavItemComponent)
	public children!: QueryList<HeaderNavItemComponent>;

	constructor() {
		this.id = HeaderNavListComponent.nextId++;
	}

	public ngAfterContentInit(): void {
		this.updateChildren();
		this.children.changes.subscribe(() => this.updateChildren());
	}

	private updateChildren(): void {
		setTimeout(() => {
			this.children.forEach(c => {
				c.nested = true;
			});
		});
	}
}